plus:'<path d="M12 5v14M5 12h14"/>',
calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2"/>',
arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
chevron:'<path d="m9 5 7 7-7 7"/>',
clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
wallet:'<path d="M20 8V5H5a2 2 0 0 1 0-4h13M5 5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h15V8H5"/><path d="M20 12h-6v5h6M16 14.5h.01"/>',
check:'<path d="m5 12 4 4L19 6"/>',
close:'<path d="m6 6 12 12M6 18 18 6"/>',
download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
